'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isInt64Array = require( '@stdlib/assert/is-int64array' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var Int64Array = require( './../lib' );


// FUNCTIONS //

/**
* Comparison function.
*
* @private
* @param {Int64} a - first value for comparison
* @param {Int64} b - second value for comparison
* @returns {number} comparison result
*/
function compareFcn( a, b ) {
	return a.lo - b.lo;
}


// MAIN //

bench( format( '%s:toSorted', pkg ), function benchmark( b ) {
	var arr;
	var out;
	var i;

	arr = new Int64Array( 10 );

	// Benchmark worst case scenario (i.e., every element is compared and written to the output array)...
	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.toSorted();
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isInt64Array( out ) ) {
		b.fail( 'should return a Int64Array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::compare_function:toSorted', pkg ), function benchmark( b ) {
	var arr;
	var out;
	var i;

	arr = new Int64Array( 10 );

	// Benchmark worst case scenario (i.e., every element is compared and written to the output array)...
	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.toSorted( compareFcn );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isInt64Array( out ) ) {
		b.fail( 'should return a Int64Array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
